/** Direct children of an issue, oldest first (creation time, then number). */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
  scope: ArchiveScope = {},
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .orderBy(issues.createdAt, issues.number)
    .all();

  return rows.map((row) => toIssue(row));
}

/** Every issue below `issueId` at any depth, archived ones included. */
export async function listDescendantIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const found: Issue[] = [];
  const seen = new Set<string>([issueId]);
  let frontier: IssueId[] = [issueId];
  while (frontier.length > 0) {
    const rows = getDb()
      .select()
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.parentId, frontier),
        ),
      )
      .all();
    frontier = [];
    for (const row of rows) {
      if (seen.has(row.id)) continue;
      seen.add(row.id);
      found.push(toIssue(row));
      frontier.push(row.id as IssueId);
    }
  }
  return found;
}

