    if (next.length > 0) height += 1;
    level = next;
  }
  return height;
}

/**
 * Places an issue under a parent of its own project, or makes it a root issue
 * again (`parentId: null`). Its sub-issues move with it, so the move is judged
 * by where the deepest of them would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    if (input.parentId === issue.id) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const parent = await requireParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );
    const below = await issueRepo.listDescendantIssues(input.orgId, issue.id);
    if (below.some((row) => row.id === parent.id)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const deepest =
      (await depthOf(input.orgId, parent)) + 1 + subtreeHeight(issue, below);
    if (deepest > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  if (issue.parentId === input.parentId) return issue;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    issue.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct, live sub-issues, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issue.id);
}

/** Counts over every live issue below an issue, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const live = (await issueRepo.listDescendantIssues(orgId, issue.id)).filter(
    (row) => row.archivedAt === null,
  );
  const closed = live.filter((row) =>
    CLOSED_ISSUE_STATUSES.includes(row.status),
  ).length;

  return { total: live.length, open: live.length - closed, closed };
}
